         ...decision,
       };
     }

     return {
       kind: "ok" as const,
       attendanceEventId,
       state: outcomeToAttendanceState(decision.outcome),
       checkedInAt: now,
       courseCode: course?.code ?? "",
       venueName: venue?.name ?? "",
       ...decision,
     };
   },
 });

