+      }
+    }
+    expect(canFollowInPipeline("corrected", "verified")).toBe(false);
+  });
+
+  it("treats corrections as overwrites, not pipeline steps", () => {
+    for (const prev of INTERMEDIATES) {
+      expect(canFollowInPipeline(prev, "corrected")).toBe(false);
+    }
+  });
