// Wait for the mutation to settle — either the row leaves the queue or an error appears.
await expect
  .poll(
    async () => {
      const hidden = (await queueRow.count()) === 0 || !(await queueRow.isVisible().catch(() => false));
      const alertText = await facultyPage
        .getByRole("alert")
        .textContent()
        .catch(() => null);
      if (alertText !== null && alertText.trim().length > 0) return `alert:${alertText}`;
      return hidden ? "hidden" : "visible";
    },
    { timeout: 30_000 },
  )
  .toBe("hidden");

// The original stays visible to the student, now marked corrected.
await studentPage.reload();

